/**
 * 配置文件集成测试：验证寻香公开政策、原生数量、往返与装配一致。输入为原公开板子 JSON 的真实读取、游戏／板子 loader 及字面政策修改；角色、阵营、数量和冲突断言保留，不把文件 I/O 标为纯单元输入。
 */
import path from "node:path";
import { test, expect } from "bun:test";
import { readFileSync } from "node:fs";
import {
  parseBoardDefinition,
  boardDefinitionFromConfig,
} from "../../../../src/runtime/config/board_definition";
import { loadBoardDefinition } from "../../../../src/runtime/config/load_board_definition";
import { parseRuntimeConfig } from "../../../../src/runtime/config/parse_config";
import { resolveGameSetup } from "../../../../src/runtime/config/resolve_game_setup";
import { bootstrapGame } from "../../../../src/app/bootstrap";
import { fragrantPairSeerTwelveConfig as config } from "../../../../src/runtime/scenarios/fragrant_pair_seer_twelve";
import { isFragrantPairSeerPreset } from "../../../../src/rulesets";
import { Role, Camp } from "../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../src/core/domain/components/names";

const root = path.resolve(import.meta.dir, "../../../../.."),
  id = "awa_fragrant_pair_seer_12_v1";

const raw = JSON.parse(readFileSync(root + "/configs.example/boards/" + id + ".json", "utf8"));

test("public example load, roundtrip, game resolve and bootstrap agree", async () => {
  const resolved = await loadBoardDefinition(root + "/configs.example", id);
  expect(resolved.config).toEqual(config);
  expect(parseBoardDefinition(boardDefinitionFromConfig(id, config)).config).toEqual(config);
  const rt = parseRuntimeConfig({
    environment: {},
    providers: { default: "fake", items: { fake: { type: "openai", apiKey: "synthetic-only" } } },
    agents: {
      default: "deepseek_v4_flash",
      items: { deepseek_v4_flash: { kind: "llm", provider: "fake", model: "fake" } },
    },
    game: JSON.parse(
      readFileSync(root + "/configs.example/games/twelve_player_fragrant_pair_seer.json", "utf8"),
    ),
  });
  const setup = resolveGameSetup(rt, {}, resolved);
  expect(setup.boardConfig).toEqual(config);
  const g = bootstrapGame(setup.boardConfig);
  expect(g.playerIds).toHaveLength(12);
  // ID 来自完整 bootstrap 名单；非空类型说明不增加运行检查或修复缺失槽。
  for (const row of config.roleSetups)
    expect(
      g.playerIds.filter((i) => g.world.getComponent(i, COMPONENT.Role)!.role === row.role),
    ).toHaveLength(row.count);
  for (const i of g.playerIds) {
    const role = g.world.getComponent(i, COMPONENT.Role)!;
    expect(g.world.getComponent(i, COMPONENT.Camp)!.camp).toBe(
      [Role.Wolf, Role.FragrantPhantom].includes(role.role) ? Camp.Wolf : Camp.Good,
    );
    expect(g.world.getComponent(i, COMPONENT.Camp)!.camp).toBe(g.world.getComponent(i, COMPONENT.Camp)!.camp);
  }
});

test("alternate hunter policy rejected publicly and internally", () => {
  for (const deathActionPolicy of ["awa_knife_or_exile_v1", "awa_day_deaths_v1"]) {
    const r = structuredClone(raw);
    r.roles.hunter = { deathActionPolicy };
    expect(() => {
      parseBoardDefinition(r);
    }).toThrow();
    const c = { ...config, hunter: { deathActionPolicy } } as any;
    expect(isFragrantPairSeerPreset(c)).toBe(false);
    expect(() => {
      bootstrapGame(c);
    }).toThrow("fragrant_pair_seer_preset_invalid");
  }
});

test("both role policy contributions reject conflicts in either object order", () => {
  for (const bad of ["fragrant_phantom", "awakened_seer"])
    for (const reverse of [false, true]) {
      const r = structuredClone(raw);
      r.roles[bad].policy = "not_the_fixed_policy";
      if (reverse) r.roles = Object.fromEntries(Object.entries(r.roles).reverse());
      expect(() => {
        parseBoardDefinition(r);
      }).toThrow("board_config_invalid_field");
    }
  for (const omitted of ["fragrant_phantom", "awakened_seer"]) {
    const r = structuredClone(raw);
    delete r.roles[omitted];
    expect(parseBoardDefinition(r).config).toEqual(config);
  }
});

test("wrong native counts fail publicly and at bootstrap", () => {
  const r = structuredClone(raw);
  r.board.roleSetups.find((x: any) => x.role === "wolf").count = 2;
  r.board.roleSetups.find((x: any) => x.role === "villager").count = 5;
  expect(() => {
    parseBoardDefinition(r);
  }).toThrow("fragrant_pair_seer_preset_invalid");
  const c = { ...config, roleSetups: r.board.roleSetups };
  expect(() => {
    bootstrapGame(c);
  }).toThrow("fragrant_pair_seer_preset_invalid");
});

/**
 * 单元测试：验证雾鸦施法者的独立权限契约与原 owner／frame／reader。输入为内存 fixture、受控回调和畸形修改；原引用、字面值及拒绝断言为预期，不执行装配周期、模型或实体传输。
 */
import { createCampComponent, createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { World } from "../../../../src/core/domain/world";
import { Camp, type Role } from "../../../../src/core/domain/identity";
import { createRoleComponent } from "../../../../src/game/observation/role-presentation";


import { createIdentityComponent } from "../../../../src/core/domain/entities/player";
import { COMPONENT } from "../../../../src/core/domain/components/names";
import {
  createAlchemistState,
  createRavenState,
} from "../../../../src/game/mechanisms/roles/mist_raven/state";
import { MistCasterAuthority } from "../../../../src/game/mechanisms/roles/mist_raven/caster_authority";
function fixture(caster: "alchemist" | "raven_claw_wolf" = "alchemist", day = 1) {
  const world = new World(),
    id = world.createEntity(),
    role = createRoleComponent(caster as Role),
    life = createAliveComponent(),
    identity = createIdentityComponent(id, 1, "Literal Player");
  (role.privateState as Record<string, unknown>)[
    caster === "alchemist" ? "alchemist" : "ravenClaw"
  ] = caster === "alchemist" ? createAlchemistState() : createRavenState();
  world.addComponent(id, COMPONENT.Role, role);
  world.addComponent(id, COMPONENT.Camp, createCampComponent(caster === "alchemist" ? Camp.Good : Camp.Wolf));
  world.addComponent(id, COMPONENT.Alive, life);
  world.addComponent(id, COMPONENT.Identity, identity);
  const authority = new MistCasterAuthority(world, id, day, caster);
  return { world, id, role, life, identity, authority };
}
test("same-night legitimate mist update preserves authority for snake and consumes both stocks", () => {
  const { authority, role } = fixture();
  const original = (role.privateState as { readonly alchemist?: unknown }).alchemist;
  authority.commitMist([1, 2, 3], [1, 2, 3]);
  expect((role.privateState as { readonly alchemist?: unknown }).alchemist).not.toBe(original);
  expect(authority.isCurrent()).toBe(true);
  expect(authority.commitSnake(1, [1])).toMatchObject({
    mistRemaining: 0,
    healRemaining: 0,
    mistHistory: [{ day: 1, targetIds: [1, 2, 3] }],
    healHistory: [{ day: 1, targetId: 1 }],
  });
  expect(authority.isCurrent()).toBe(true);
  expect(() => authority.commitSnake(1, [1])).toThrow("snake_choice_unavailable");
});
test("raven is checked once at night start, and legitimate unseal permits an independent knife", () => {
  const { authority, role } = fixture("raven_claw_wolf", 2);
  expect(() => authority.commitRavenKnife(4, [1, 4])).toThrow("raven_night_start_required");
  expect(authority.checkRavenAtNightStart([1, 2])).toMatchObject({
    awakenedDay: 2,
    knownTeammateIds: [2],
  });
  expect(authority.isCurrent()).toBe(true);
  expect(authority.commitRavenKnife(4, [1, 2, 4])).toMatchObject({
    extraRemaining: 0,
    extraHistory: [{ day: 2, targetId: 4 }],
  });
  expect(() => authority.checkRavenAtNightStart([1])).toThrow("raven_night_start_reentry");
  const later = new MistCasterAuthority(fixtureWorld(role), 1, 3, "raven_claw_wolf");
  expect(later.checkRavenAtNightStart([1])).toMatchObject({
    awakenedDay: 2,
    knownTeammateIds: [2],
  });
});
function fixtureWorld(role: ReturnType<typeof createRoleComponent>) {
  const world = new World(),
    id = world.createEntity();
  world.addComponent(id, COMPONENT.Role, role);
  world.addComponent(id, COMPONENT.Camp, createCampComponent(Camp.Wolf));
  world.addComponent(id, COMPONENT.Alive, createAliveComponent());
  world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, 1, "Literal Player"));
  return world;
}
test("one night owner cannot rerun the sealed start check after wolves decrease", () => {
  const { authority } = fixture("raven_claw_wolf");
  expect(authority.checkRavenAtNightStart([1, 2, 3])).toMatchObject({
    awakenedDay: null,
    knownTeammateIds: [],
  });
  expect(() => authority.checkRavenAtNightStart([1, 2])).toThrow("raven_night_start_reentry");
  expect(authority.state()).toMatchObject({ awakenedDay: null });
});
for (const edit of [
  "role_object",
  "role_name",
  "camp",
  "identity_object",
  "identity_name",
  "identity_seat",
  "private_container",
  "state_equal_copy",
  "history_equal_copy",
  "stock",
  "life_object",
  "revived",
  "life_accessor",
] as const)
  test(`caster original authority rejects foreign mutation/${edit}`, () => {
    const { world, id, role, life, identity, authority } = fixture();
    switch (edit) {
      case "role_object":
        world.addComponent(id, COMPONENT.Role, createRoleComponent(role.role));
        world.addComponent(id, COMPONENT.Camp, { camp: world.getComponent(id, COMPONENT.Camp)!.camp });
        break;
      case "role_name":
        role.role = "villager" as Role;
        break;
      case "camp":
        world.getComponent(id, COMPONENT.Camp)!.camp = Camp.Wolf;
        break;
      case "identity_object":
        world.addComponent(id, COMPONENT.Identity, { ...identity });
        break;
      case "identity_name":
        identity.name = "Changed";
        break;
      case "identity_seat":
        identity.seat = 2;
        break;
      case "private_container":
        (role as { privateState: Readonly<Record<string, unknown>> }).privateState = {
          ...role.privateState,
        };
        break;
      case "state_equal_copy":
        (role.privateState as Record<string, unknown>).alchemist = structuredClone(
          (role.privateState as { readonly alchemist?: unknown }).alchemist,
        );
        break;
      case "history_equal_copy":
        (
          (role.privateState as { readonly alchemist?: unknown }).alchemist as ReturnType<
            typeof createAlchemistState
          >
        ).mistHistory = [];
        break;
      case "stock":
        (
          (role.privateState as { readonly alchemist?: unknown }).alchemist as ReturnType<
            typeof createAlchemistState
          >
        ).healRemaining = 0;
        break;
      case "life_object":
        world.addComponent(id, COMPONENT.Alive, createAliveComponent());
        break;
      case "revived":
        life.alive = false;
        life.alive = true;
        break;
      case "life_accessor":
        Object.defineProperty(life, "alive", {
          get() {
            throw Error("must_not_read_foreign_getter");
          },
          enumerable: true,
          configurable: true,
        });
        break;
    }
    expect(authority.isCurrent()).toBe(false);
    expect(() => authority.commitMist(null, [id])).toThrow("mist_caster_authority_revoked");
  });
test("DTO copies never become authority or mutate the engine-owned inventory", () => {
  const { authority } = fixture();
  const dto = authority.state() as ReturnType<typeof createAlchemistState>;
  dto.healRemaining = 0;
  dto.mistHistory.push({ day: 1, targetIds: [1, 2, 3] });
  expect(authority.isCurrent()).toBe(true);
  expect(authority.state()).toEqual(createAlchemistState());
});
test("invalid tool selection preserves the originally owned resources", () => {
  const { authority } = fixture();
  expect(() => authority.commitMist([1, 1, 2], [1, 2, 3])).toThrow("mist_choice_target_invalid");
  expect(() => authority.commitSnake(2, [])).toThrow("snake_choice_target_invalid");
  expect(authority.state()).toEqual(createAlchemistState());
  expect(authority.isCurrent()).toBe(true);
});
test("state binding never calls a foreign array map accessor", () => {
  const { world, role } = fixture();
  let calls = 0;
  const initial = createAlchemistState();
  const prototype = Object.create(Array.prototype);
  Object.defineProperty(prototype, "map", {
    get() {
      calls++;
      throw Error("mapgetter");
    },
  });
  Object.setPrototypeOf(initial.mistHistory, prototype);
  (role.privateState as Record<string, unknown>).alchemist = initial;
  const authority = new MistCasterAuthority(world, 1, 1, "alchemist");
  expect(authority.isCurrent()).toBe(true);
  expect(authority.state()).toEqual(createAlchemistState());
  expect(calls).toBe(0);
});
for (const day of [1, 2])
  test(`nested equal mist array replacement revokes day ${day} snake authority`, () => {
    const { world, role, authority } = fixture();
    authority.commitMist([1, 2, 3], [1, 2, 3]);
    const current = day === 1 ? authority : new MistCasterAuthority(world, 1, 2, "alchemist");
    const state = (role.privateState as { readonly alchemist?: unknown }).alchemist as ReturnType<
      typeof createAlchemistState
    >;
    state.mistHistory[0]!.targetIds = [...state.mistHistory[0]!.targetIds!];
    expect(current.isCurrent()).toBe(false);
    expect(() => current.commitSnake(1, [1])).toThrow("mist_caster_authority_revoked");
    expect(state.healRemaining).toBe(1);
  });
for (const mode of ["same-value", "camp-value", "getter"] as const)
  test(`actual Camp component is bound/${mode}`, () => {
    const { world, id, authority } = fixture();
    const camp = world.getComponent(id, COMPONENT.Camp)!;
    let calls = 0;
    if (mode === "same-value") world.addComponent(id, COMPONENT.Camp, { ...camp });
    else if (mode === "camp-value") camp.camp = Camp.Wolf;
    else
      Object.defineProperty(camp, "camp", {
        get() {
          calls++;
          return Camp.Good;
        },
        enumerable: true,
        configurable: true,
      });
    expect(authority.isCurrent()).toBe(false);
    expect(calls).toBe(0);
    expect(() => authority.commitSnake(null, [])).toThrow("mist_caster_authority_revoked");
    expect(calls).toBe(0);
  });

test("original first death preserves paid knowledge while never allowing another resource commit", () => {
  const { authority, life } = fixture("raven_claw_wolf", 2);
  authority.checkRavenAtNightStart([1, 2]);
  authority.commitRavenKnife(3, [1, 2, 3]);
  life.alive = false;
  expect(authority.isCurrent()).toBe(false);
  expect(authority.isCurrent(true)).toBe(true);
  expect(authority.state(true)).toMatchObject({ knownTeammateIds: [2], extraRemaining: 0 });
  expect(() => authority.commitRavenKnife(null, [1, 2])).toThrow("mist_caster_authority_revoked");
  life.alive = true;
  expect(authority.isCurrent(true)).toBe(false);
});
test("a replaced body cannot use the first-death read permission", () => {
  const { world, authority, id, life } = fixture();
  life.alive = false;
  world.addComponent(id, COMPONENT.Alive, createAliveComponent(false));
  expect(authority.isCurrent(true)).toBe(false);
  expect(() => authority.state(true)).toThrow("mist_caster_authority_revoked");
});

/**
 * 单元测试：验证夜贵族独立 authority 与原 owner／frame／reader。输入为内存 fixture、受控回调和畸形修改；原字面值、身份快照和拒绝断言为预期，不执行装配周期、模型或实体传输。
 */
import { createAliveComponent } from "../../../../src/game/observation/component-presentation";
import { expect, test } from "bun:test";
import { COMPONENT } from "../../../../src/core/domain/components/names";

import { createRoleComponent } from "../../../../src/game/observation/role-presentation";
import { Role, Camp } from "../../../../src/core/domain/identity";
import { nobleBodyAuthorityFixture } from "../../../support/features/noble-secret-body/drivers/authority";
import {
  beginNobleBodyNight,
  openSecretBodyChoice,
  openServantChoice,
  clearServantFromHunt,
  expireServantAtNightEnd,
  closeServantForDeath,
  resolveSecretBodyDamage,
  closeNobleBodyNight,
  snapshotNobleBodyAuthority,
  consumeSecretBodyExile,
} from "../../../../src/game/mechanisms/roles/noble_secret_body/authority";

test("original contract survives normal noble death, occupies N3, expires once before damage", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1);
  f.finish(1);
  f.night(2, 4, 3);
  f.finish(2);
  f.life(1).alive = false;
  beginNobleBodyNight(f.world, 3, () => true);
  openSecretBodyChoice(f.world, 3).commit(3);
  expect(() => openServantChoice(f.world, 3)).toThrow();
  const expiry = expireServantAtNightEnd(f.world, 3);
  expect(expiry).toEqual({ contractId: "servant:night:2", targetId: 3, cause: "servant_expiry" });
  expect(() => expireServantAtNightEnd(f.world, 3)).toThrow("night_noble_expiry_already_processed");
  closeNobleBodyNight(f.world, 3, "normal");
  const damage = resolveSecretBodyDamage(f.world, 3, { 3: ["servant_expiry"] });
  expect(damage).toEqual({ blocked: { targetId: 3, cause: "servant_expiry" }, sources: {} });
  expect(snapshotNobleBodyAuthority(f.world).noble.contracts[0]!.status).toEqual({
    kind: "expired",
    day: 3,
  });
});
for (const end of ["hunt", "death"] as const)
  test(`N2 ${end} closes old contract so N3 can create a new one`, () => {
    const f = nobleBodyAuthorityFixture();
    f.night(1);
    f.finish(1);
    f.night(2, null, 3);
    if (end === "hunt")
      expect(clearServantFromHunt(f.world, 2, 3)).toEqual({
        contractId: "servant:night:2",
        targetId: 3,
      });
    else {
      f.life(3).alive = false;
      expect(closeServantForDeath(f.world, 2, 3)).toEqual({
        contractId: "servant:night:2",
        targetId: 3,
      });
    }
    f.finish(2);
    f.night(3, null, 4);
    expect(snapshotNobleBodyAuthority(f.world).noble.contracts[1]).toMatchObject({
      createdNight: 3,
      targetId: 4,
      status: { kind: "pending" },
    });
  });
test("expiry followed by abort retains submitted expiry but leaves body unspent", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1);
  f.finish(1);
  f.night(2, null, 3);
  f.finish(2);
  beginNobleBodyNight(f.world, 3, () => true);
  openSecretBodyChoice(f.world, 3).commit(3);
  expect(expireServantAtNightEnd(f.world, 3)?.targetId).toBe(3);
  closeNobleBodyNight(f.world, 3, "aborted");
  expect(() => resolveSecretBodyDamage(f.world, 3, { 3: ["servant_expiry"] })).toThrow(
    "noble_body_night_unavailable",
  );
  const state = snapshotNobleBodyAuthority(f.world);
  expect(state.body.body.kind).toBe("intact");
  expect(state.noble.contracts[0]!.status.kind).toBe("expired");
  expect(() => beginNobleBodyNight(f.world, 3, () => true)).toThrow("noble_body_night_unavailable");
});
test("paid body protects one source and never falls back again to itself", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1, 3);
  expireServantAtNightEnd(f.world, 1);
  closeNobleBodyNight(f.world, 1, "normal");
  expect(
    resolveSecretBodyDamage(f.world, 1, { 3: ["poison", "wolf_kill"], 2: ["servant_expiry"] }),
  ).toEqual({
    blocked: { targetId: 3, cause: "wolf_kill" },
    sources: { 3: ["poison"], 2: ["servant_expiry"] },
  });
  const state = snapshotNobleBodyAuthority(f.world);
  expect(state.body.lastChoice).toEqual({ day: 1, targetId: 3 });
  expect(state.body.body).toEqual({ kind: "night_spent", day: 1, targetId: 3, cause: "wolf_kill" });
  expect(() => resolveSecretBodyDamage(f.world, 1, {})).toThrow(
    "secret_body_damage_already_processed",
  );
  expect(() => consumeSecretBodyExile(f.world, 1)).toThrow("secret_body_unavailable");
});
test("paid original body effect survives its caster's first actual death", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1, 3);
  f.life(2).alive = false;
  expireServantAtNightEnd(f.world, 1);
  closeNobleBodyNight(f.world, 1, "normal");
  expect(resolveSecretBodyDamage(f.world, 1, { 3: ["poison"] })).toEqual({
    blocked: { targetId: 3, cause: "poison" },
    sources: {},
  });
});
for (const replace of ["role", "state", "life", "revive"] as const)
  test(`awaiting body choice cannot consume replacement ${replace}`, () => {
    const f = nobleBodyAuthorityFixture();
    beginNobleBodyNight(f.world, 1, () => true);
    const choice = openSecretBodyChoice(f.world, 1);
    if (replace === "role")
      {
        f.world.addComponent(2, COMPONENT.Role, createRoleComponent(Role.Villager));
        f.world.addComponent(2, COMPONENT.Camp, { camp: Camp.Good });
      }
    if (replace === "state")
      (f.roles[1]!.privateState as Record<string, unknown>).secretBody = structuredClone(
        (f.roles[1]!.privateState as { readonly secretBody?: unknown }).secretBody,
      );
    if (replace === "life") f.world.addComponent(2, COMPONENT.Alive, createAliveComponent());
    if (replace === "revive") {
      f.life(2).alive = false;
      f.life(2).alive = true;
    }
    expect(choice.isCurrent()).toBe(false);
    expect(() => choice.commit(3)).toThrow("secret_body_choice_revoked");
    closeNobleBodyNight(f.world, 1, "aborted");
  });
test("a replaced target life cannot receive pending expiry", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1);
  f.finish(1);
  f.night(2, null, 3);
  f.finish(2);
  f.world.addComponent(3, COMPONENT.Alive, createAliveComponent());
  expect(() => beginNobleBodyNight(f.world, 3, () => true)).toThrow("noble_body_owner_revoked");
});
test("normal action closure waits for required steps and next night waits for final damage", () => {
  const f = nobleBodyAuthorityFixture();
  beginNobleBodyNight(f.world, 1, () => true);
  expect(() => closeNobleBodyNight(f.world, 1, "normal")).toThrow("noble_body_night_incomplete");
  openSecretBodyChoice(f.world, 1).commit(null);
  expireServantAtNightEnd(f.world, 1);
  closeNobleBodyNight(f.world, 1, "normal");
  expect(() => beginNobleBodyNight(f.world, 2, () => true)).toThrow("noble_body_night_unavailable");
  resolveSecretBodyDamage(f.world, 1, {});
  expect(() => beginNobleBodyNight(f.world, 2, () => true)).not.toThrow();
  closeNobleBodyNight(f.world, 2, "aborted");
});
test("body damage cannot consume during active action delivery or expose an early exile", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1, 3);
  expect(() => resolveSecretBodyDamage(f.world, 1, { 3: ["poison"] })).toThrow(
    "secret_body_damage_before_action_close",
  );
  expect(() => consumeSecretBodyExile(f.world, 1)).toThrow("secret_body_exile_owner_revoked");
  expect(snapshotNobleBodyAuthority(f.world).body.body.kind).toBe("intact");
  f.finish(1);
  expect(consumeSecretBodyExile(f.world, 1)).toEqual({ actorId: 2, day: 1 });
});
test("clearing an old occupied contract does not reopen its already passed choice window", () => {
  const f = nobleBodyAuthorityFixture();
  f.night(1);
  f.finish(1);
  f.night(2, null, 3);
  f.finish(2);
  beginNobleBodyNight(f.world, 3, () => true);
  openSecretBodyChoice(f.world, 3).commit(null);
  expect(clearServantFromHunt(f.world, 3, 3)?.targetId).toBe(3);
