    gateway.validateAndSanitize(game.world, 1, choose(4), { phase: Phase.Night, day: 1 }).error,
  ).toBe("hybrid_unavailable");
  await HYBRID_STAGE.execute(
    context(game, events, async () => {
      throw new Error("spent");
