            { kind: "role" }
          >;
        }[]
      ).push({
        day: 1,
        targetId,
        result: { kind: "role", role: Role.Villager },
      });
    const inject = () =>
      (
        ability.state.history as {
          day: number;
          targetId: import("@ai-werewolf-arena/game-contract").EntityId;
          result: Extract<
            import("@ai-werewolf-arena/game-contract").InspectionResult,
